

# =====================================================================
# THE CELLS OF CHAPTER 26 — F1 the first fruits (26:1-11), F2 the removal and the confession (26:12-15), F3 the covenant formula (26:16-19) — each ask a case; the verdicts DATA rows or PARAMETERS, never the ink's
# =====================================================================
def the_first_fruits(case, data):
    """F1 — Deut 26:1-11 — ONE LINE first_fruits_declared writing first_fruits_basket_commanded, first_fruits_declaration_commanded, first_fruits_recital_commanded and first_fruits_set_before_altar_commanded (STATUSES) and rejoicing_before_the_lord_commanded REUSED at 26:11; the kin by CALL (calendar — first-ness, the species fetched; korach — the grant to the priest; place_name — the place, the eras, the rejoicing's first entry; food_tithe — the rejoicing's second; joseph and exodus_story — the recital's retelling; chukat — 26:7's clause; naso — the holy tongue); the cases Bikkurim 1-3, Terumot 11:3 and Peah 1:1 the exam rows"""
    del P_[:]
    ask = case['ask']
    if ask == 'when_you_come_into_the_land_and_dwell_in_it':
        ink('26:1', "'AND IT SHALL BE, WHEN YOU COME INTO THE LAND which the LORD your God gives you for an inheritance, AND POSSESS IT AND DWELL IN IT' — entering, possessing and settling BEFORE the duty; the closest kin %s (the king's law 17:14 — the entry's three commandments)" % (KINC[(26, 1)][0],))
        move("the Sifrei 297:1-3 (read whole at the reading); cold_run_place_name (CALL) — PN.the_place_chosen(the_three_commandments_of_the_entry) = %s" % (PN_THREE[0],), "'when you come … and possess … and dwell' — do the duty after the possession and the settling; the three commandments of the entry — the king, Amalek, the House (Sanhedrin 20b by the place's cell); the settler who brings before the division accepted against")
        dat("THE LINE first_fruits_declared at the counter's day (40, 11, 1), STATUTE by form, no marker; the readback row 26:1 SUPPLIED with the line's four writes; the exam's person the settler who brings before the land is divided — refused")
        return out("when you come into the land and dwell in it (26:1) — the first fruits' duty after the possession and the settling (the Sifrei 297:1-3; the entry's three commandments by CALL — %s): THE LINE first_fruits_declared at the counter's day; the settler before the division refused" % (PN_THREE[0],), ['first_fruits_basket_commanded', 'first_fruits_declaration_commanded', 'first_fruits_recital_commanded', 'first_fruits_set_before_altar_commanded'])
    if ask == 'the_first_of_all_the_fruit_in_a_basket_to_the_place':
        ink('26:2', "'you shall take OF THE FIRST OF ALL THE FRUIT OF THE GROUND which you bring from your land … and put it IN A BASKET and go to THE PLACE which the LORD your God chooses' — 'of the first' and not all the first; 'your land'; the basket a vessel; the place the chosen one (12:5's cell)")
        move("the Sifrei 297:4-9, 298:1-2 (read whole at the reading — the species by the two loaves' analogy, I2, checked in MIDDOT.md); MISHNAH BIKKURIM 1:1, 1:2, 1:3, 3:8 and TERUMOT 11:3 (the exam rows, read whole — 1:1-2 CITED IN THE SPINE'S OWN HEBREW at 297); cold_run_calendar (CALL) — CA.first_fruits = %s; cold_run_korach (CALL) — KO.the_gifts(bikkurim) = %s, (the_best_triad) = %s; cold_run_place_name (CALL) — PN.the_place_chosen(the_stations_six_rows) read" % (CA_FF[0], KO_BIK[0], KO_TRIAD[0]), "ONLY THE SEVEN SPECIES, not dates of the hills nor fruit of the valleys nor olives not choice, NOT BEFORE SHAVUOT (Bikkurim 1:3 — the men of Mount Zevoim refused); no liquids but from olives and grapes (Terumot 11:3); the one who plants in his own and bends into another's does not bring, sharecroppers and robbers do not bring — 'the first fruits of YOUR land' (Bikkurim 1:1-2; Exodus 23:19 by the calendar's cell — first-ness the ink's, the species the transmitted list); the basket — the rich in silver and gold, the poor in peeled willow, THE BASKETS AND THE FIRST FRUITS TO THE PRIESTS (Bikkurim 3:8); Shiloh and the House by the place's eras")
        dat("THE WRITE first_fruits_basket_commanded — a STATUS on israel_people at the chapters' own day (DL2); THE PARAMETERS the_species (Bikkurim 1:3; Terumot 11:3), the_bringers_and_the_reciters (Bikkurim 1:1-2), the_baskets (Bikkurim 3:8); the exam's person the one who brings dates from the hills — refused, not of the seven")
        return out("the first of all the fruit in a basket to the place (26:2) — only the seven species and not before Shavuot, from your own land, in a basket of silver or of peeled willow to the chosen place (the Sifrei 297:4-9, 298:1-2; Bikkurim 1:1-3, 3:8, Terumot 11:3; the calendar's first-ness %s and korach's grant %s by CALL): THE WRITE first_fruits_basket_commanded, a STATUS on Israel at the chapters' own day; the bringer of the hills' dates refused" % (CA_FF[0], KO_BIK[0]), ['first_fruits_basket_commanded'])
    if ask == 'i_declare_this_day_to_the_priest':
        ink('26:3', "'and you shall come to the priest who is in those days and say to him: I DECLARE THIS DAY to the LORD your God that I have come into the land which the LORD swore to our fathers to give us' — the priest of the hour; 'this day' once a year; 'swore' the seven's homograph, not counted (the reading's parser)")
        move("the Sifrei 299:1-4 (read whole — the headless piska inside 26:3); MISHNAH BIKKURIM 1:4, 1:5, 1:6, 1:8, 1:10 (the exam rows, read whole — 1:4 and 1:10 CITED IN THE HEBREW at 299); cold_run_festivals_judges (CALL) — FJ.the_three_pilgrimages(not_empty) = %s (the appearing at the feasts the frame)" % (FJ_EMPTY[0],), "no ingratitude — ONCE A YEAR; robbed, rotted, stolen, lost or unclean: he brings others in their place and does not recite, no fifth (Bikkurim 1:8 — the replacement); the convert brings and does not recite 'which the LORD swore to OUR FATHERS' unless his mother is an Israelite (1:4 — two arms); the guardian, the agent, the slave, the woman, the one of doubtful sex bring and do not recite 'which YOU have given ME' (1:5); two trees in another's field, the well dried, the tree cut — brings and does not recite, R. Meir and R. Judah recite (1:6); FROM SHAVUOT TO THE FEAST BRINGS AND RECITES, FROM THE FEAST TO CHANUKAH BRINGS AND DOES NOT RECITE, R. Judah ben Betera recites (1:6 — THE WINDOW); beyond the Jordan — R. Yose the Galilean not (1:10)")
        dat("THE WRITE first_fruits_declaration_commanded — a STATUS on israel_people at the chapters' own day (DL2); THE PARAMETERS the_first_fruits_window (Bikkurim 1:3, 1:6, 1:10 — A CLOCK DATUM on the calendar's keys atzeret and sukkot_1: %s), the_replacement (1:8), the_bringers_and_the_reciters (1:4-6); the exam's person the convert whose mother is a gentile — brings and does not recite" % (WE.CAL_PARAMS['the_first_fruits_window'].get('idiom') if isinstance(WE.CAL_PARAMS.get('the_first_fruits_window'), dict) else 'on file',))
        return out("I declare this day to the priest (26:3) — once a year; the convert brings and does not recite unless his mother is an Israelite; the guardian, the agent, the slave and the woman bring and do not recite; from Shavuot to the Feast recites, from the Feast to Chanukah brings without reciting, not before Shavuot; the replacement without a fifth (the Sifrei 299:1-4; Bikkurim 1:4-6, 1:8, 1:10; the appearing's %s by CALL): THE WRITE first_fruits_declaration_commanded, a STATUS on Israel at the chapters' own day; the convert of a gentile mother brings without reciting" % (FJ_EMPTY[0],), ['first_fruits_declaration_commanded'])
    if ask == 'the_recital_a_wandering_aramean':
        ink('26:4-10', "'and the priest shall take the basket from your hand and SET IT DOWN BEFORE THE ALTAR … and you shall ANSWER AND SAY before the LORD your God: A WANDERING ARAMEAN WAS MY FATHER, and he went down to Egypt and sojourned there FEW IN NUMBER … and the Egyptians dealt ill with us … AND WE CRIED TO THE LORD … and the LORD brought us out WITH A MIGHTY HAND AND AN OUTSTRETCHED ARM … a land FLOWING WITH MILK AND HONEY' — 'few in number' 28:62's twin (%d shared), 'with a mighty hand and an outstretched arm' 5:15's (%d), 'flowing with milk and honey' Exodus 3:8's (%d); the closest kin of 26:9 %s" % (TWIN['28:62 vs 26:5'], TWIN['26:8 vs 5:15'], TWIN['26:9 vs Exod 3:8'], KINC[(26, 9)][0]))
        move("the Sifrei 300:1-2, 301:1-24 (read whole — the waving at 300:2, the holy tongue at 301:1 by I2 with 27:14, 'Laban the Aramean sought to destroy my father' at 301:3 = Onkelos 26:5; 301:8-24 the Haggadah's rows); MISHNAH SOTAH 7:2 and BIKKURIM 2:4, 3:7 (the exam rows, read whole); cold_run_naso (CALL) — NS.blessing(language) = %s (Sotah 33b's bless/bless with 27:12); cold_run_joseph (CALL) — JO.seventy = %s; cold_run_second_tablets (CALL) — ST(seventy_persons) = %s; cold_run_chukat (CALL) — CK.edom_and_hor(firstfruits_clauses) = %s; cold_run_exodus_story (CALL) — the bondage, the cry and the going out the tape's own lines (enslaved %s, cry_heard %s, plague_struck %s the counts unmoved)" % (NS_LANG[0], JO_70, ST_70[0], CK_CLAUSES[0], KIN_COUNTS['enslaved'], KIN_COUNTS['cry_heard'], KIN_COUNTS['plague_struck']), "the priest takes the basket and WAVES it, the owner's hand beneath (Bikkurim 2:4 — 'from your hand'); THE RECITAL IN THE HOLY TONGUE by 27:14's 'answer and say' (Sotah 7:2 — the recital, the shoe's rite, the blessings and the curses, the priests' blessing in the holy tongue); Laban the Aramean who sought to destroy my father (Onkelos); the seventy, the affliction, the cry (26:7's clause in the Edom letter — Numbers 20:16 and Deuteronomy 26:7 alone), the mighty hand the pestilence and the arm the sword, the ten plagues by pairs, 'this place' the Temple, milk and honey the five nations' land: THE RECITAL A RETELLING of the tape's own story — the readback's T1 rows against came_to_egypt, enslaved, cry_heard, brought_out, plague_struck and the milk and honey's promise, never a second act; the prompting of all who recite (Bikkurim 3:7 — a DATA row)")
        dat("THE WRITE first_fruits_recital_commanded — a STATUS on israel_people at the chapters' own day (DL2); THE PARAMETER the_tongue (Sotah 7:1-2 — the recital in the holy tongue, the confession in any: one parameter two arms); the_recitals_lines a DATA row (the tape's kinds by first verse); the exam's person the one who recites in Aramaic — accepted against")
        return out("the recital, a wandering Aramean (26:5-10) — in the holy tongue by 27:14's analogy, the priest waving the basket, Laban who sought to destroy my father, the seventy, the bondage, the cry, the plagues, the milk and honey: a RETELLING of the tape's own story graded as reference rows (the Sifrei 300-301; Sotah 7:2, Bikkurim 2:4, 3:7; naso's %s, joseph's %s and chukat's %s by CALL): THE WRITE first_fruits_recital_commanded, a STATUS on Israel at the chapters' own day; the reciter in Aramaic refused" % (NS_LANG[0], JO_70, CK_CLAUSES[0]), ['first_fruits_recital_commanded', 'first_fruits_set_before_altar_commanded'])
    if ask == 'set_it_down_bow_and_rejoice_with_the_levite_and_the_stranger':
        ink('26:10-11', "'and you shall SET IT DOWN before the LORD your God AND BOW DOWN before the LORD your God; AND YOU SHALL REJOICE IN ALL THE GOOD which the LORD your God has given you and your house, you and the Levite and the stranger in your midst' — the two settings (26:4, 26:10); the rejoicing's third seat on the tape (12:7, 14:26; 27:7 THE SOURCE)")
        move("the Sifrei 301:25-37 (read whole — the two settings at 301:31 = Bikkurim 3:1; every kind of joy; 301:32 = Bikkurim 1:5; 301:35 = Bikkurim 3:4; 301:37 = Maaser Sheni 5:14's converts); MISHNAH BIKKURIM 3:1, 3:4 and MAASER SHENI 5:14 (the exam rows, read whole); cold_run_food_tithe (CALL) — FT.the_far_place(the_rejoicing) = %s (its reuse the precedent); cold_run_place_name (CALL) — PN.the_place_chosen(eat_there_and_rejoice) = %s (the first entry; the Sifrei 63:9 naming the first fruits in 12:6's offering of the hand); Tosefta Shekalim 3:24 — no Temple, no first fruits (the daemon's own guard)" % (FT_REJ[0], PN_REJ[0]), "the fig that ripened tied with a reed — 'these are first fruits'; R. Shimon's second designation after plucking (Bikkurim 3:1 — the setting aside, two arms); acquired attached, the whole field, responsible, requiring a sacrifice, a song, waving and lodging (2:4); the flute, King Agrippas with the basket on his shoulder, the Levites' song (3:4 — the rite's history); the Levite and the stranger at the rejoicing — converts without a share bring and do not recite (5:14); THE REJOICING = the peace offerings by I2 with 27:7 (the Sifrei 107:16, 64:2, 69:1, 138:1 — every one a REFERENCE for us)")
        dat("THE WRITES first_fruits_set_before_altar_commanded — a STATUS on israel_people at the chapters' own day (DL2) — and rejoicing_before_the_lord_commanded REUSED at 26:11 (a third entry; the recon's count %s before, %s after — REUSE_COUNTS %s); THE PARAMETERS the_setting_aside (Bikkurim 3:1), the_temple_condition (Tosefta Shekalim 3:24; Bikkurim 2:4); the exam's person the one who designates the fig again after plucking — R. Shimon's arm recorded" % (REUSE_BEFORE['rejoicing_before_the_lord_commanded'], REUSE_AFTER['rejoicing_before_the_lord_commanded'], REUSE_COUNTS['rejoicing_before_the_lord_commanded']))
        return out("set it down, bow and rejoice with the Levite and the stranger (26:10-11) — the two settings and the fig tied with a reed, the whole field acquired and responsible, the flute and the king's basket, the converts at the rejoicing without reciting; no Temple, no first fruits (the Sifrei 301:25-37; Bikkurim 3:1, 2:4, 3:4, Maaser Sheni 5:14; Tosefta Shekalim 3:24; food_tithe's %s and place_name's %s by CALL): THE WRITES first_fruits_set_before_altar_commanded, a STATUS, and rejoicing_before_the_lord_commanded REUSED — a third entry on Israel at the chapters' own day; the second designation after plucking R. Shimon's arm" % (FT_REJ[0], PN_REJ[0]), ['first_fruits_set_before_altar_commanded', 'rejoicing_before_the_lord_commanded'])
    return 'no verdict in span', [], list(P_)


def the_removal_and_the_confession(case, data):
    """F2 — Deut 26:12-15 — ONE LINE tithe_confession_declared writing tithe_removal_commanded and tithe_confession_commanded (STATUSES), tithe_in_mourning_barred, tithe_in_uncleanness_barred and tithe_for_the_dead_barred (BLOCKS) and poor_tithe_owed REUSED at 26:12; the kin by CALL (food_tithe — the removal's date on file, the measures, the four in want, the dead's two seats; korach — the tithe's clauses and order; chatat — the mourner; place_name — 12:17's warning grounded here; seven_nations and seducers — the oath's form); the cases Maaser Sheni 5:6, 5:10-14, Peah 4:11, 8:5 and Sotah 7:1 the exam rows"""
    del P_[:]
    ask = case['ask']
    if ask == 'when_you_have_finished_tithing_in_the_third_year':
        ink('26:12', "'WHEN YOU HAVE FINISHED TITHING all the tithe of your yield IN THE THIRD YEAR, THE YEAR OF THE TITHE' — 'finished' the verse's own clock; 'the year of the tithe' one tithe; the tithe's two tokens starred by the store (the ten's homograph — the reading's parser %s)" % (PARSE[(26, 12)][2],))
        move("the Sifrei 302:1 (read whole — the end-analogy with 31:10 and 15:1 weighed and REFUSED by the verse's own 'finished'; MISHNAH MAASER SHENI 5:6 CITED IN THE SPINE'S OWN HEBREW at 302:1 and 109:3, the exam row read whole); the Sifrei 109:4-5 (the seventh year exempt; one tithe not two); cold_run_food_tithe (CALL) — FT.the_third_year(the_removal_date) = %s, (one_tithe_not_two) = %s, (the_seventh_year_by_the_cycle) = %s" % (FT_REMOVAL[0], FT_ONE[0], FT_SEVENTH[0]), "THE REMOVAL AT THE EVE OF THE LAST FESTIVAL DAY OF PASSOVER of the fourth and the seventh year (others: the first) — the terumah and the terumah of the tithe to their owners, the first tithe to its owner, the poor's tithe to its owner, the second tithe and the first fruits removed in every place; R. Shimon: the first fruits to the priests like terumah; the cooked dish — the House of Shammai removes, the House of Hillel as removed (Maaser Sheni 5:6 — the arms recorded); the poor man's tithe REPLACES the second in the third and the sixth year; the seventh year exempt")
        dat("THE WRITE tithe_removal_commanded — a STATUS on israel_people at the chapters' own day (DL2) — and poor_tithe_owed REUSED at 26:12 (a second entry — 14:28's the first; the recon's %s before, %s after — REUSE_COUNTS %s); the_removal_date READ BY CALL — the parameter on file (12b's row, the keys passover_1 and passover_7; this runner exercising it); the exam's person the householder who removes at Shavuot of the fourth year — refused, the eve of Passover's last festival day the date" % (REUSE_BEFORE['poor_tithe_owed'], REUSE_AFTER['poor_tithe_owed'], REUSE_COUNTS['poor_tithe_owed']))
        return out("when you have finished tithing in the third year (26:12) — the removal at the eve of the last festival day of Passover of the fourth and the seventh year, every tithe to its owner, the second tithe and the first fruits removed, the cooked dish the two Houses' arms; one tithe not two, the seventh year exempt (the Sifrei 302:1, 109:4-5; Maaser Sheni 5:6 in the spine's own Hebrew; food_tithe's %s, %s and %s by CALL): THE WRITES tithe_removal_commanded, a STATUS, and poor_tithe_owed REUSED — a second entry on Israel at the chapters' own day; the removal at Shavuot refused" % (FT_REMOVAL[0], FT_ONE[0], FT_SEVENTH[0]), ['tithe_removal_commanded', 'poor_tithe_owed'])
    if ask == 'given_to_the_levite_the_stranger_the_orphan_and_the_widow':
        ink('26:12', "'and have GIVEN IT TO THE LEVITE, THE STRANGER, THE ORPHAN AND THE WIDOW, that they may eat in your gates and be satisfied' — the four in want (14:29's list); 'in your gates' the poor's tithe eaten anywhere; 'and be satisfied' the measure")
        move("the Sifrei 303:1-4 (read whole — the headless piska inside 26:13; 303:2 = MISHNAH PEAH 8:5 the exam row read whole; 303:4 = MISHNAH SOTAH 7:1 the exam row read whole); MISHNAH PEAH 4:11 (the exam row — the ant holes); cold_run_food_tithe (CALL) — FT.the_third_year(the_measures) = %s, (the_four_in_want) = %s, (the_gifts_exempt) = %s; cold_run_second_tablets (CALL) — ST(the_orphan_and_the_widow) = %s; cold_run_persons_poor_court (CALL) — PP.fathers_and_sons(the_strangers_and_the_orphans_justice) = %s" % (FT_MEASURES[0], FT_FOUR[0], FT_GIFTS[0], ST_ORPHAN[0], PP_JUST[0]), "each his share till satisfied — at the threshing floor HALF A KAV OF WHEAT OR A KAV OF BARLEY (R. Meir: half a kav of barley), a kav and a half of spelt, a kav of dried figs or a maneh of pressed figs (R. Akiva: a peras), half a log of wine (R. Akiva: a quarter), a quarter of oil (R. Akiva: an eighth); Abba Shaul — enough to sell and buy two meals (Peah 8:5 — the measures at the floor); the ant holes' doubtful gleanings are gleanings (Peah 4:11 — R. Meir; the poor's doubt); not expelled from the land (303:1 — the Nevalta clan); THE CONFESSION IN ANY LANGUAGE (Sotah 7:1 — the warning's portion, the tithe's confession, the Shema, the prayer, the grace, the two oaths) against the recital's holy tongue (7:2)")
        dat("THE PARAMETERS the_measures_at_the_floor (Peah 8:5 — by CALL to food_tithe's parameter), the_tongue's other arm (Sotah 7:1 — the confession in any language); the four in want by CALL; the exam's person the Levite given a kav of barley at the floor — satisfied, the measure met")
        return out("given to the Levite, the stranger, the orphan and the widow (26:12) — each his share till satisfied: half a kav of wheat or a kav of barley at the floor with R. Meir's, R. Akiva's and Abba Shaul's arms; the ant holes' doubt the poor's; the confession in any language (the Sifrei 303:1-4; Peah 8:5, 4:11, Sotah 7:1; food_tithe's %s and %s, second_tablets' %s by CALL): the Levite given a kav of barley satisfied" % (FT_MEASURES[0], FT_FOUR[0], ST_ORPHAN[0]), ['accepted'])
    if ask == 'i_have_removed_the_holy_from_the_house':
        ink('26:13', "'AND YOU SHALL SAY BEFORE THE LORD YOUR GOD: I HAVE REMOVED THE HOLY FROM THE HOUSE and have given it to the Levite, the stranger, the orphan and the widow, according to all Your commandment which You commanded me; I have not transgressed Your commandments and I have not forgotten' — the six clauses' referents; 'according to all Your commandment' the order")
        move("the Sifrei 303:5-14 (read whole); MISHNAH MAASER SHENI 5:10 (CITED at 303:6 and in Onkelos 26:13), 5:11 (at 303:11-14) and 5:14 (at 301:37) — the exam rows read whole; cold_run_korach (CALL) — KO.the_tithe(wrong_order) = %s, (from_it) = %s, (kind_for_kind) = %s; cold_run_priesthood (CALL) — PR.holy_food read (the priests' portions' class)" % (KO_ORDER[0], KO_FROM[0], KO_KIND[0]), "AT MINCHAH ON THE LAST FESTIVAL DAY THEY CONFESSED (5:10 — THE HOUR); 'the holy' the second tithe and the fourth year's fruit, 'to the Levite' the Levite's tithe, 'and also' the terumah and the terumah of the tithe, 'to the stranger, the orphan and the widow' the poor's tithe, the gleanings, the forgotten and the corner though they do not bar the confession, 'from the house' the dough offering (5:10 — the clauses); 'according to all Your commandment' — THE SECOND BEFORE THE FIRST BARS THE CONFESSION (5:11 — the order of the tithes; korach's wrong order valid at the Numbers seat, the confession barred here); 'I have not transgressed' — not from one kind for another, not the plucked for the attached nor the attached for the plucked, not the new for the old nor the old for the new; 'I have not forgotten' — to bless You and to mention Your Name (5:11); Israelites and mamzerim confess, not converts nor freed slaves (no share in the land); R. Meir — not priests and Levites; R. Yose — the Levitical cities (5:14 — the confessors)")
        dat("THE WRITE tithe_confession_commanded — a STATUS on israel_people at the chapters' own day (DL2); THE PARAMETERS the_confessions_hour (Maaser Sheni 5:10 — A CLOCK DATUM on the removal's keys, passover_7 at minchah), the_confessions_clauses (5:10-13), the_order_of_the_tithes (5:11), the_confessors (5:14 — three arms); the exam's person the one who separated the second tithe before the first — barred from the confession")
        return out("I have removed the holy from the house (26:13) — the confession at minchah on the last festival day: the second tithe and the fourth year's fruit, the Levite's tithe, the terumah, the poor's tithe, the dough offering; the second before the first bars it; not kind for kind, not the plucked for the attached, not the new for the old; to bless and to mention the Name; Israelites and mamzerim confess, not converts (the Sifrei 303:5-14; Maaser Sheni 5:10-11, 5:14; korach's %s, %s and %s by CALL): THE WRITE tithe_confession_commanded, a STATUS on Israel at the chapters' own day; the one who tithed the second before the first barred from the confession" % (KO_ORDER[0], KO_FROM[0], KO_KIND[0]), ['tithe_confession_commanded'])
    if ask == 'not_in_mourning_not_in_uncleanness_not_for_the_dead':
        ink('26:14', "'I HAVE NOT EATEN OF IT IN MY MOURNING, AND I HAVE NOT REMOVED OF IT IN UNCLEANNESS, AND I HAVE NOT GIVEN OF IT FOR THE DEAD; I have hearkened to the voice of the LORD my God, I have done according to all that You commanded me' — three negations (the reading's five in the chapter); 'for the dead' 14:1's word at the book's two seats; Onkelos 'I have RECEIVED THE MEMRA' for the hearkening")
        move("the Sifrei 303:15-19 (read whole); MISHNAH MAASER SHENI 5:12 (the exam row, read whole — CITED at 303:17-19); the Sifrei 72:5 (12:17's warning grounded by 26:14 — read whole at chapter 12 and again here); cold_run_food_tithe (CALL) — FT.the_sons_and_the_cuttings(for_the_dead) = %s; cold_run_chatat (CALL) — CT.share(onen) = %s (the a fortiori from 26:14 for the holy of the generations); cold_run_place_name (CALL) — PN.the_profane_slaughter(the_impure_tithes_warning) = %s" % (FT_DEAD[0], CT_ONEN['v'], PN_WARN[0]), "eaten in mourning BARS the confession; removed in uncleanness — whether it was unclean and I clean or I unclean and it clean — BARS it; 'not given to the dead' — no coffin nor shrouds, not to other mourners (Maaser Sheni 5:12); R. Eliezer and R. Akiva at 303:18-19; the mourner's share of the holy things by the a fortiori from 26:14 (Leviticus 10:19's Aaron — chatat's cell); 12:17's 'you may not eat within your gates' the impure tithe's warning grounded on 26:14's 'in uncleanness' (72:5 — the place's cell)")
        dat("THE WRITES tithe_in_mourning_barred, tithe_in_uncleanness_barred and tithe_for_the_dead_barred — three BLOCKS on israel_people at the chapters' own day (DL2); the exam's person the mourner who ate of the second tithe on the day of his dead — barred from the confession")
        return out("not in mourning, not in uncleanness, not for the dead (26:14) — eaten in mourning bars the confession, removed in uncleanness bars it, given for a coffin or shrouds bars it; the mourner's share by the a fortiori; 12:17's warning grounded here (the Sifrei 303:15-19, 72:5; Maaser Sheni 5:12; food_tithe's %s, chatat's %s and place_name's %s by CALL): THE WRITES tithe_in_mourning_barred, tithe_in_uncleanness_barred and tithe_for_the_dead_barred — three BLOCKS on Israel at the chapters' own day; the mourner who ate barred from the confession" % (FT_DEAD[0], CT_ONEN['v'], PN_WARN[0]), ['tithe_in_mourning_barred', 'tithe_in_uncleanness_barred', 'tithe_for_the_dead_barred'])
    if ask == 'look_down_and_bless':
        ink('26:15', "'LOOK DOWN FROM YOUR HOLY HABITATION, FROM HEAVEN, AND BLESS YOUR PEOPLE ISRAEL and the ground which You have given us, AS YOU SWORE TO OUR FATHERS, a land flowing with milk and honey' — the oath's AS_WHEN form; 'flowing with milk and honey' the formula's fifteen Torah seats (%s the closest kin — Joshua's, not read)" % (KINC[(26, 15)][0][0],))
        move("the Sifrei 303:20 (read whole — 'we have done what You decreed, do what You promised'); MISHNAH MAASER SHENI 5:13 (the exam row, read whole); cold_run_seven_nations (CALL) — SN.the_holy_people(the_oath) = %s (the patriarchs' oath lines by kind); cold_run_seducers (CALL) — SE(as_he_swore_to_your_fathers) = %s (13:18's form of the pointer)" % (SN_OATH[0], SE_OATH[0]), "'look down from Your holy habitation' — we have done what You decreed upon us, do what You promised us; 'and bless Your people Israel' — with sons and daughters; 'and the ground' — with dew and rain and the offspring of cattle; 'as You swore to our fathers, a land flowing with milk and honey' — that You put taste in the produce (Maaser Sheni 5:13 — the confession's close); the chosen House at 303:17")
        dat("the oath to the fathers the pointer's AS_WHEN form at 26:15 — the patriarchs' oath lines by kind (a RUN CITATION if the census demands; no register seat — the finder's %s); the readback row 26:15 VARIANT against the oath's lines; the exam's person the reader of the confession's close — accepted" % (GL_R,))
        return out("look down and bless (26:15) — we have done what You decreed, do what You promised: sons and daughters, dew and rain and the offspring of cattle, the taste in the produce; 'as You swore to our fathers' the oath's form (the Sifrei 303:20; Maaser Sheni 5:13; seven_nations' %s and seducers' %s by CALL): the confession's close accepted" % (SN_OATH[0], SE_OATH[0]), ['accepted'])
    return 'no verdict in span', [], list(P_)


def the_covenant_formula(case, data):
    """F3 — Deut 26:16-19 — ONE LINE covenant_formula_declared writing statutes_this_day_commanded, israel_declared_the_lord_god and lord_declared_israel_treasure_people (STATUSES) and high_above_all_nations_promised and holy_people_promised (HEAVEN entries) — THE VERSES WITHOUT A SPINE ROW, compiled on Onkelos and the ink alone; the kin by CALL (hear_o_israel — the heart and the soul; exodus_story and seven_nations — the treasure and the holy people; food_tithe — 14:2's pair; covenant_at_horeb — the frame); no case of the Mishnah"""
    del P_[:]
    ask = case['ask']
    if ask == 'this_day_the_lord_commands_you_to_do_these_statutes':
        ink('26:16', "'THIS DAY THE LORD YOUR GOD COMMANDS YOU TO DO THESE STATUTES AND JUDGMENTS; and you shall keep and do them WITH ALL YOUR HEART AND WITH ALL YOUR SOUL' — 'this day' the counter's day (the thirteen seats of 'this day' in the three chapters); 6:5's pair; the statutes' block of the register (12:1, 28:69] closing at the footer")
        move("NO SPINE ROW (the Sifrei runs 303 on 26:15 to 304 on 31:14 — the covenant formula uncited); Onkelos 26:16 plain; cold_run_hear_o_israel (CALL) — HI.the_four_duties(the_seven) = %s (6:5's creed the pair's seat, the duties' cell); cold_run_covenant_at_horeb (CALL) — CH.the_assembly_called(hear_learn_keep_do) = %s (5:1's four verbs the frame's kin)" % (HI_SEVEN[0], CH_FOUR[0]), "the statutes and the judgments commanded THIS DAY — the counter's day; keep and do with all the heart and all the soul — the Shema's pair at its second Deuteronomy seat outside the creed; the register's block of the statutes' declaration (12:1's header) closes at 28:69's footer — its class DAEMONS computed by the census, undeclared")
        dat("THE WRITE statutes_this_day_commanded — a STATUS on israel_people at the chapters' own day (DL2); the readback row 26:16 SUPPLIED with the line's five writes; the register's footer at 28:69 the census's (the_three_covenants a DATA row); the exam's person the hearer of 'this day' — accepted")
        return out("this day the LORD commands you to do these statutes (26:16) — the counter's day; with all the heart and all the soul, 6:5's pair; no spine row, Onkelos and the ink alone (hear_o_israel's %s and covenant_at_horeb's %s by CALL): THE WRITE statutes_this_day_commanded, a STATUS on Israel at the chapters' own day; the hearer of this day accepted" % (HI_SEVEN[0], CH_FOUR[0]), ['statutes_this_day_commanded'])
    if ask == 'the_lord_you_have_declared_this_day_to_be_your_god':
        ink('26:17', "'THE LORD YOU HAVE DECLARED THIS DAY to be your God, and to walk in His ways and to keep His statutes, His commandments and His judgments and to hearken to His voice' — the causative of 'say' at 26:17-18 alone in the Bible; the mutual declaration's first half")
        move("Onkelos 26:17 — 'you have CHOSEN the LORD this day', 'in ways that are RIGHT before Him', 'to RECEIVE HIS MEMRA' (the Word) for the voice; cold_run_exodus_story (CALL) — ES.sinai = %s (the offer and the people's answer — covenant_offered the tape's line at Exodus 19:5)" % (ES_SINAI,), "the rare verb rendered CHOSEN — Israel's half of the mutual declaration; the readback row 26:17 VARIANT against the tape's covenant_offered and entered_the_covenant (Exodus 24:3, 24:7 — 'all that the LORD has spoken we will do'; the counts %s and %s unmoved)" % (KIN_COUNTS['entered_the_covenant'], KIN_COUNTS['covenant_declared']))
        dat("THE WRITE israel_declared_the_lord_god — a STATUS on israel_people at the chapters' own day (DL2); no case of the Mishnah — the readback row VARIANT; the exam's person the one who declares and does not walk — accepted against")
        return out("the LORD you have declared this day to be your God (26:17) — Onkelos 'you have chosen', 'to receive His Memra': Israel's half of the mutual declaration, the readback row variant against the offer at Sinai and the covenant entered (exodus_story's %s by CALL): THE WRITE israel_declared_the_lord_god, a STATUS on Israel at the chapters' own day" % (ES_SINAI,), ['israel_declared_the_lord_god'])
    if ask == 'the_lord_has_declared_you_this_day_his_treasured_people':
        ink('26:18', "'AND THE LORD HAS DECLARED YOU THIS DAY TO BE HIS TREASURED PEOPLE, AS HE SPOKE TO YOU, and to keep all His commandments' — 'a treasured people' 7:6 and 14:2's phrase (the formula's three Torah seats); 'AS HE SPOKE TO YOU' the first AS_WHEN pointer")
        move("Onkelos 26:18 — 'a BELOVED people'; cold_run_seven_nations (CALL) — SN.the_holy_people(holy_people) = %s (19:5-6's treasure read back with 14:2; treasured_people the tape's heaven entry, count %s UNMOVED); cold_run_food_tithe (CALL) — FT.the_sons_and_the_cuttings(the_holy_people) = %s (eighteen of nineteen tokens with 7:6)" % (SN_HOLY[0], KIN_COUNTS['treasured_people'], FT_HOLY[0]), "'as He spoke to you' — Exodus 19:5-6's offer: 'you shall be to Me a treasure from all the peoples … a kingdom of priests and a holy nation' (the tape's covenant_offered by kind): THE POINTER at 26:18 a RUN CITATION reference (the census's own demand filed from the gate's print); the LORD's half of the mutual declaration")
        dat("THE WRITE lord_declared_israel_treasure_people — a STATUS on israel_people at the chapters' own day (DL2); the pointer 26:18 RUN_CITATION of Exodus 19:5-6 (the five AS_WHEN pointers predicted); the exam's person the reader who asks where He spoke it — Exodus 19:5, accepted")
        return out("the LORD has declared you this day His treasured people (26:18) — Onkelos 'a beloved people'; 'as He spoke to you' Exodus 19:5-6's offer, the pointer a run citation (seven_nations' %s and food_tithe's %s by CALL; treasured_people unmoved): THE WRITE lord_declared_israel_treasure_people, a STATUS on Israel at the chapters' own day" % (SN_HOLY[0], FT_HOLY[0]), ['lord_declared_israel_treasure_people'])
    if ask == 'high_above_all_nations_a_holy_people_as_he_spoke':
        ink('26:19', "'and TO SET YOU HIGH ABOVE ALL THE NATIONS which He has made, for praise, for a name and for glory, and that you be A HOLY PEOPLE TO THE LORD YOUR GOD, AS HE SPOKE' — 'high above all' 28:1's twin alone in the Torah (%d tokens shared); 'a holy people' 7:6, 14:2 and 28:9 ahead; 'as He spoke' the second AS_WHEN pointer" % (TWIN['26:19 vs 28:1'],))
        move("Onkelos 26:19 — 'HIGHEST over all the peoples', 'a holy people BEFORE the LORD'; cold_run_seven_nations (CALL) — SN.the_holy_people(chose_you) = %s; cold_run_release_firstborn (CALL) — RF.the_needy_and_the_blessing(the_hearkening) = %s (28:1's condition the twin's seat)" % (SN_CHOSE[0], RF_HEAR[0]), "the promise's arm of the mutual declaration — CONDITIONAL in blessings_for_hearing's form (the entry OPEN on the condition; 7:12's 'because you hear', Exodus 19:5's 'if you will hear'); 'as He spoke' 7:6 and 14:2 — the pointer a RUN CITATION reference; no case of the Mishnah")
        dat("THE WRITES high_above_all_nations_promised and holy_people_promised — HEAVEN entries on israel_people at the chapters' own day (DL2), conditional in blessings_for_hearing's form; the pointer 26:19 RUN_CITATION of 7:6 and 14:2; the readback row VARIANT against covenant_offered and hearing_blessed; the exam's person the people set high who hearkens — the promise open")
        return out("high above all nations, a holy people, as He spoke (26:19) — 28:1's twin, 7:6 and 14:2's phrase, Onkelos 'highest over all the peoples'; the promise's arm conditional in blessings_for_hearing's form; 'as He spoke' a run citation (seven_nations' %s and release_firstborn's %s by CALL): THE WRITES high_above_all_nations_promised and holy_people_promised, HEAVEN entries on Israel at the chapters' own day, open on the condition" % (SN_CHOSE[0], RF_HEAR[0]), ['high_above_all_nations_promised', 'holy_people_promised'])
    return 'no verdict in span', [], list(P_)
